          "id": "code-ml-10-1-ch10_1_scratch",
          "title": "First-Principles NumPy: Replikasi Crossover Teorema Ng & Jordan (2001)",
          "language": "python",
          "filename": "10_1_ng_jordan_crossover_scratch.py",
          "code": "import numpy as np\nfrom scipy.optimize import minimize\n\ndef fit_predict_pooled_gnb(X_tr: np.ndarray, y_tr: np.ndarray, X_te: np.ndarray) -> np.ndarray:\n    \"\"\"First-principles Pooled-Variance Gaussian Naive Bayes (generatif linier).\"\"\"\n    mu0 = X_tr[y_tr == 0].mean(axis=0)\n    mu1 = X_tr[y_tr == 1].mean(axis=0)\n    r0 = X_tr[y_tr == 0] - mu0\n    r1 = X_tr[y_tr == 1] - mu1\n    var = (np.sum(r0 ** 2, axis=0) + np.sum(r1 ** 2, axis=0)) / max(len(X_tr) - 2, 1) + 1e-6\n    p1 = (float(np.sum(y_tr == 1)) + 1.0) / (len(X_tr) + 2.0)\n    w = (mu1 - mu0) / var\n    b = -0.5 * float(np.sum((mu1 ** 2 - mu0 ** 2) / var)) + float(np.log(p1 / (1.0 - p1)))\n    return (X_te @ w + b >= 0.0).astype(int)\n\ndef fit_predict_logreg_lbfgs(X_tr: np.ndarray, y_tr: np.ndarray, X_te: np.ndarray, lam: float = 1e-3) -> np.ndarray:\n    \"\"\"First-principles Logistic Regression MLE (diskriminatif linier) via L-BFGS-B.\"\"\"\n    n, d = X_tr.shape\n    Xa = np.column_stack([np.ones(n), X_tr])\n    def obj(w: np.ndarray):\n        z = np.clip(Xa @ w, -30.0, 30.0)\n        p = 1.0 / (1.0 + np.exp(-z))\n        loss = float(np.sum(np.logaddexp(0.0, z) - y_tr * z)) + 0.5 * lam * float(np.sum(w[1:] ** 2))\n        grad = Xa.T @ (p - y_tr)\n        grad[1:] += lam * w[1:]\n        return loss, grad\n    res = minimize(obj, np.zeros(d + 1), jac=True, method=\"L-BFGS-B\", options={\"maxiter\": 80})\n    return (np.column_stack([np.ones(len(X_te)), X_te]) @ res.x >= 0.0).astype(int)\n\ndef sample_ng_jordan_data(rng: np.random.Generator, n: int, d: int = 60):\n    \"\"\"6 fitur redundan berkorelasi (rho=0.95, melanggar NB) + 16 fitur sinyal independen + 38 derau.\"\"\"\n    y = rng.integers(0, 2, size=n)\n    sgn = np.where(y == 1, 1.0, -1.0)\n    X = rng.normal(0.0, 1.0, size=(n, d))\n    z_weak = rng.normal(0.0, 1.0, size=(n, 1)) + 0.30 * sgn[:, None]\n    X[:, :6] = 0.95 * z_weak + 0.31 * rng.normal(0.0, 1.0, size=(n, 6))\n    X[:, 6:22] += 0.38 * sgn[:, None]\n    return X, y\n\nrng = np.random.default_rng(42)\nd = 60\nX_test, y_test = sample_ng_jordan_data(rng, 3000, d)\n\nprint(\"=== Replikasi Teorema Ng & Jordan (2001): Crossover Small-Data vs Asymptotic (d=60) ===\")\nprint(\"n_train | Gen (NB) Err | Disc (LogReg) Err | Pemenang & Selisih Error\")\nprint(\"-\" * 74)\nfor n_tr in [20, 40, 80, 180, 450, 1200]:\n    nb_errs, lr_errs = [], []\n    for _ in range(25):\n        X_tr, y_tr = sample_ng_jordan_data(rng, n_tr, d)\n        nb_errs.append(float(np.mean(fit_predict_pooled_gnb(X_tr, y_tr, X_test) != y_test)))\n        lr_errs.append(float(np.mean(fit_predict_logreg_lbfgs(X_tr, y_tr, X_test) != y_test)))\n    e_nb = float(np.mean(nb_errs))\n    e_lr = float(np.mean(lr_errs))\n    winner = \"Generatif (NB)\" if e_nb < e_lr else \"Diskriminatif (LR)\"\n    diff = abs(e_nb - e_lr) * 100.0\n    print(f\"{n_tr:7d} | {e_nb*100:11.2f}% | {e_lr*100:16.2f}% | {winner:18s} (-{diff:.2f} pp)\")",
          "expectedOutput": "=== Replikasi Teorema Ng & Jordan (2001): Crossover Small-Data vs Asymptotic (d=60) ===\nn_train | Gen (NB) Err | Disc (LogReg) Err | Pemenang & Selisih Error\n--------------------------------------------------------------------------\n     20 |       22.55% |            22.91% | Generatif (NB)     (-0.35 pp)\n     40 |       16.31% |            16.52% | Generatif (NB)     (-0.21 pp)\n     80 |       13.13% |            14.52% | Generatif (NB)     (-1.40 pp)\n    180 |       12.54% |            12.29% | Diskriminatif (LR) (-0.25 pp)\n    450 |       12.29% |            11.79% | Diskriminatif (LR) (-0.51 pp)\n   1200 |       11.83% |             8.10% | Diskriminatif (LR) (-3.73 pp)",
          "actualOutput": "=== Replikasi Teorema Ng & Jordan (2001): Crossover Small-Data vs Asymptotic (d=60) ===\nn_train | Gen (NB) Err | Disc (LogReg) Err | Pemenang & Selisih Error\n--------------------------------------------------------------------------\n     20 |       22.55% |            22.91% | Generatif (NB)     (-0.35 pp)\n     40 |       16.31% |            16.52% | Generatif (NB)     (-0.21 pp)\n     80 |       13.13% |            14.52% | Generatif (NB)     (-1.40 pp)\n    180 |       12.54% |            12.29% | Diskriminatif (LR) (-0.25 pp)\n    450 |       12.29% |            11.79% | Diskriminatif (LR) (-0.51 pp)\n   1200 |       11.83% |             8.10% | Diskriminatif (LR) (-3.73 pp)",
