          "id": "code-ml-10-1-ch10_1_sklearn",
          "title": "Scikit-Learn: Oracle Bayes Error & Gerbang Deteksi OOD via Marginal log p(x)",
          "language": "python",
          "filename": "10_1_bayes_optimal_ood_gate.py",
          "code": "import numpy as np\nfrom scipy.special import logsumexp\nfrom scipy.stats import multivariate_normal\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\n\nrng = np.random.default_rng(101)\nd = 6\nmu0 = np.zeros(d)\nmu1 = np.array([1.1, -0.9, 0.7, -0.5, 0.4, -0.3])\n# Matriks kovarians berkorelasi bersama (homoskedastik)\nidx = np.arange(d)\ncov = 0.6 ** np.abs(idx[:, None] - idx[None, :])\npi0, pi1 = 0.65, 0.35\n\ndef draw_gmm(n: int):\n    y = rng.binomial(1, pi1, size=n)\n    X = np.zeros((n, d))\n    n1 = int(y.sum())\n    X[y == 0] = rng.multivariate_normal(mu0, cov, size=n - n1)\n    X[y == 1] = rng.multivariate_normal(mu1, cov, size=n1)\n    return X, y\n\nX_tr, y_tr = draw_gmm(600)\nX_id, y_id = draw_gmm(1500)\n\n# 1. Hitung Bayes Optimal Classifier & Bayes Error Rate eksak (Oracle)\nlp0 = np.log(pi0) + multivariate_normal.logpdf(X_id, mean=mu0, cov=cov)\nlp1 = np.log(pi1) + multivariate_normal.logpdf(X_id, mean=mu1, cov=cov)\nbayes_pred = (lp1 > lp0).astype(int)\nbayes_err = float(np.mean(bayes_pred != y_id))\n\n# 2. Latih LDA (Generatif) vs LogisticRegression (Diskriminatif)\nlda = LinearDiscriminantAnalysis(store_covariance=True).fit(X_tr, y_tr)\nlr = LogisticRegression(C=1.0, max_iter=500).fit(X_tr, y_tr)\n\nlda_err = float(np.mean(lda.predict(X_id) != y_id))\nlr_err = float(np.mean(lr.predict(X_id) != y_id))\n\n# 3. Uji sampel Out-of-Distribution (OOD): jauh dari kedua distribusi kelas (+10 sigma)\nX_ood = rng.normal(loc=0.0, scale=1.0, size=(300, d)) + np.array([9.0, -8.0, 7.0, -6.0, 5.0, -4.0])\n\n# Densitas marginal log p(x) = log(sum_k pi_k N(x | mu_k, Sigma)) dari model LDA terlatih\ndef lda_marginal_log_density(model: LinearDiscriminantAnalysis, X: np.ndarray) -> np.ndarray:\n    cov_hat = model.covariance_\n    comp = []\n    for k in range(len(model.classes_)):\n        comp.append(np.log(model.priors_[k]) + multivariate_normal.logpdf(X, mean=model.means_[k], cov=cov_hat))\n    return logsumexp(np.vstack(comp), axis=0)\n\nlogp_id = lda_marginal_log_density(lda, X_id)\nlogp_ood = lda_marginal_log_density(lda, X_ood)\n# Ambang OOD: persentil ke-1 dari log p(x) in-distribution\ntau_ood = float(np.percentile(logp_id, 1.0))\nood_flagged_rate = float(np.mean(logp_ood < tau_ood))\n\n# Bandingkan kepercayaan (max predicted prob) LogisticRegression vs LDA pada data OOD\nlr_ood_conf = float(np.mean(np.max(lr.predict_proba(X_ood), axis=1)))\nlda_ood_conf = float(np.mean(np.max(lda.predict_proba(X_ood), axis=1)))\nood_labels = np.concatenate([np.zeros(len(X_id)), np.ones(len(X_ood))])\nood_auroc_gen = float(roc_auc_score(ood_labels, -np.concatenate([logp_id, logp_ood])))\n# Skor ketidakyakinan diskriminatif: entropi / -max_prob\nood_auroc_lr_conf = float(roc_auc_score(ood_labels, -np.concatenate([\n    np.max(lr.predict_proba(X_id), axis=1), np.max(lr.predict_proba(X_ood), axis=1)\n])))\n\nprint(\"=== Perbandingan vs Bayes Optimal Classifier (Homoskedastik Gaussian, d=6) ===\")\nprint(f\"Oracle Bayes Optimal Error Rate : {bayes_err*100:.2f}%\")\nprint(f\"Generatif LDA Error Rate        : {lda_err*100:.2f}% (gap vs Bayes: +{(lda_err-bayes_err)*100:.2f} pp)\")\nprint(f\"Diskriminatif LogReg Error Rate : {lr_err*100:.2f}% (gap vs Bayes: +{(lr_err-bayes_err)*100:.2f} pp)\")\nprint(\"=== Audit Deteksi Out-of-Distribution (OOD +10 sigma) ===\")\nprint(f\"Mean Max-Prob pada OOD -> LogReg: {lr_ood_conf:.6f} | LDA Posterior: {lda_ood_conf:.6f} (sama-sama overconfident!)\")\nprint(f\"Median log p(x) Generatif -> In-Dist: {np.median(logp_id):.2f} | OOD: {np.median(logp_ood):.2f}\")\nprint(f\"OOD Detection AUROC -> Marginal log p(x) Generatif: {ood_auroc_gen:.4f} | LogReg Confidence: {ood_auroc_lr_conf:.4f}\")\nprint(f\"OOD Flag Rate pada Ambang p1 In-Dist (tau={tau_ood:.2f}): {ood_flagged_rate*100:.2f}%\")",
          "expectedOutput": "=== Perbandingan vs Bayes Optimal Classifier (Homoskedastik Gaussian, d=6) ===\nOracle Bayes Optimal Error Rate : 4.80%\nGeneratif LDA Error Rate        : 5.60% (gap vs Bayes: +0.80 pp)\nDiskriminatif LogReg Error Rate : 5.73% (gap vs Bayes: +0.93 pp)\n=== Audit Deteksi Out-of-Distribution (OOD +10 sigma) ===\nMean Max-Prob pada OOD -> LogReg: 1.000000 | LDA Posterior: 1.000000 (sama-sama overconfident!)\nMedian log p(x) Generatif -> In-Dist: -7.63 | OOD: -397.53\nOOD Detection AUROC -> Marginal log p(x) Generatif: 1.0000 | LogReg Confidence: 0.0000\nOOD Flag Rate pada Ambang p1 In-Dist (tau=-13.09): 100.00%",
