          "code": "import numpy as np\nfrom scipy.stats import multivariate_normal\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import log_loss\n\nrng = np.random.default_rng(77)\nd = 8\nmu0 = np.zeros(d)\nmu1 = np.array([1.2, 1.0, -0.9, -0.8, 0.6, 0.5, -0.4, 0.3])\n# Matriks kovarians dengan korelasi blok tinggi\ncov = np.full((d, d), 0.55)\nnp.fill_diagonal(cov, 1.0)\npi1 = 0.5\n\ndef gen_samples(n: int):\n    y = rng.binomial(1, pi1, size=n)\n    X = np.zeros((n, d))\n    n1 = int(y.sum())\n    X[y == 0] = rng.multivariate_normal(mu0, cov, size=n - n1)\n    X[y == 1] = rng.multivariate_normal(mu1, cov, size=n1)\n    return X, y\n\nX_tr, y_tr = gen_samples(1000)\nX_te, y_te = gen_samples(1200)\n\n# Estimasi parameter Gaussian Generatif dari training set (bersih)\nmu0_h = X_tr[y_tr == 0].mean(axis=0)\nmu1_h = X_tr[y_tr == 1].mean(axis=0)\nXc0 = X_tr[y_tr == 0] - mu0_h\nXc1 = X_tr[y_tr == 1] - mu1_h\ncov_h = (Xc0.T @ Xc0 + Xc1.T @ Xc1) / (len(X_tr) - 2)\npi1_h = float(y_tr.mean())\nmed_tr = np.median(X_tr, axis=0)\n\n# Latih LogisticRegression (Diskriminatif) pada training set bersih\nlr = LogisticRegression(C=1.0, max_iter=500).fit(X_tr, y_tr)\n\n# Simulasikan 35% fitur hilang secara acak (MCAR) pada saat inferensi produksi\nmask_missing = rng.random(X_te.shape) < 0.35\n# Pastikan tiap baris masih menyisakan minimal 1 fitur teramati\nfor i in range(len(X_te)):\n    if np.all(mask_missing[i]):\n        mask_missing[i, 0] = False\n\n# A. Diskriminatif + Imputasi Median Training\nX_te_imp = np.where(mask_missing, med_tr[None, :], X_te)\np_lr_imp = lr.predict_proba(X_te_imp)[:, 1]\n\n# B. Generatif + Marginalisasi Eksak p(x_obs | y) = N(x_obs; mu_{y,obs}, Sigma_{obs,obs})\np_gen_marg = np.zeros(len(X_te))\nfor i in range(len(X_te)):\n    obs = np.where(~mask_missing[i])[0]\n    x_obs = X_te[i, obs]\n    cov_oo = cov_h[np.ix_(obs, obs)]\n    l0 = np.log(1.0 - pi1_h) + multivariate_normal.logpdf(x_obs, mean=mu0_h[obs], cov=cov_oo)\n    l1 = np.log(pi1_h) + multivariate_normal.logpdf(x_obs, mean=mu1_h[obs], cov=cov_oo)\n    p_gen_marg[i] = 1.0 / (1.0 + np.exp(np.clip(l0 - l1, -35.0, 35.0)))\n\n# Baseline data lengkap tanpa missing\np_lr_full = lr.predict_proba(X_te)[:, 1]\nl0_f = np.log(1.0 - pi1_h) + multivariate_normal.logpdf(X_te, mean=mu0_h, cov=cov_h)\nl1_f = np.log(pi1_h) + multivariate_normal.logpdf(X_te, mean=mu1_h, cov=cov_h)\np_gen_full = 1.0 / (1.0 + np.exp(np.clip(l0_f - l1_f, -35.0, 35.0)))\n\nprint(\"=== Audit Ketahanan Missing Features Saat Inferensi (35% Fitur Hilang Acak) ===\")\nprint(f\"Baseline Lengkap -> Gen Acc: {np.mean((p_gen_full>=0.5)==y_te)*100:.2f}% (LogLoss {log_loss(y_te, p_gen_full):.4f}) | \"\n      f\"LogReg Acc: {np.mean((p_lr_full>=0.5)==y_te)*100:.2f}% (LogLoss {log_loss(y_te, p_lr_full):.4f})\")\nprint(f\"35% Missing      -> Gen Marginalisasi Eksak: Acc {np.mean((p_gen_marg>=0.5)==y_te)*100:.2f}% | LogLoss {log_loss(y_te, p_gen_marg):.4f}\")\nprint(f\"35% Missing      -> LogReg Imputasi Median : Acc {np.mean((p_lr_imp>=0.5)==y_te)*100:.2f}% | LogLoss {log_loss(y_te, p_lr_imp):.4f}\")\nprint(f\"Keunggulan Marginalisasi Eksak atas Imputasi Median: \"\n      f\"+{(np.mean((p_gen_marg>=0.5)==y_te)-np.mean((p_lr_imp>=0.5)==y_te))*100:.2f} pp Acc, \"\n      f\"{log_loss(y_te, p_gen_marg) - log_loss(y_te, p_lr_imp):+.4f} LogLoss\")",
          "expectedOutput": "=== Audit Ketahanan Missing Features Saat Inferensi (35% Fitur Hilang Acak) ===\nBaseline Lengkap -> Gen Acc: 94.42% (LogLoss 0.1428) | LogReg Acc: 93.83% (LogLoss 0.1468)\n35% Missing      -> Gen Marginalisasi Eksak: Acc 88.08% | LogLoss 0.2568\n35% Missing      -> LogReg Imputasi Median : Acc 87.00% | LogLoss 0.3309\nKeunggulan Marginalisasi Eksak atas Imputasi Median: +1.08 pp Acc, -0.0741 LogLoss",
          "actualOutput": "=== Audit Ketahanan Missing Features Saat Inferensi (35% Fitur Hilang Acak) ===\nBaseline Lengkap -> Gen Acc: 94.42% (LogLoss 0.1428) | LogReg Acc: 93.83% (LogLoss 0.1468)\n35% Missing      -> Gen Marginalisasi Eksak: Acc 88.08% | LogLoss 0.2568\n35% Missing      -> LogReg Imputasi Median : Acc 87.00% | LogLoss 0.3309\nKeunggulan Marginalisasi Eksak atas Imputasi Median: +1.08 pp Acc, -0.0741 LogLoss",
