          "code": "import numpy as np\nfrom scipy.linalg import eigh\n\nrng = np.random.default_rng(202)\n# 3 kelas heteroskedastik dalam R^4 (kovarians dan orientasi berbeda tiap kelas)\nmus_true = [\n    np.array([0.0, 0.0, 0.0, 0.0]),\n    np.array([2.2, 1.4, -0.6, 0.5]),\n    np.array([1.0, -2.0, 1.2, -0.8]),\n]\ncovs_true = [\n    np.array([[2.5, 1.6, 0.4, 0.0], [1.6, 1.8, 0.3, 0.0], [0.4, 0.3, 1.0, 0.2], [0.0, 0.0, 0.2, 1.0]]),\n    np.array([[0.6, -0.35, 0.1, 0.0], [-0.35, 0.7, -0.1, 0.0], [0.1, -0.1, 1.2, 0.3], [0.0, 0.0, 0.3, 0.8]]),\n    np.array([[1.4, -0.9, 0.2, 0.1], [-0.9, 2.2, -0.4, 0.0], [0.2, -0.4, 0.7, -0.2], [0.1, 0.0, -0.2, 1.5]]),\n]\n\ndef draw_3class(n_per_class: int):\n    Xs, ys = [], []\n    for k in range(3):\n        Xs.append(rng.multivariate_normal(mus_true[k], covs_true[k], size=n_per_class))\n        ys.append(np.full(n_per_class, k, dtype=int))\n    return np.vstack(Xs), np.concatenate(ys)\n\nX_tr, y_tr = draw_3class(250)\nX_te, y_te = draw_3class(400)\nn_tr, d = X_tr.shape\nK = 3\n\n# 1. Estimasi parameter kelas & Pooled Covariance (LDA) vs Per-Class Covariance (QDA)\nmeans = np.array([X_tr[y_tr == k].mean(axis=0) for k in range(K)])\npriors = np.array([np.mean(y_tr == k) for k in range(K)])\ncovs = [np.cov(X_tr[y_tr == k], rowvar=False, ddof=1) for k in range(K)]\nS_W = sum((np.sum(y_tr == k) - 1) * covs[k] for k in range(K))\nSigma_pool = S_W / (n_tr - K)\n\n# 2. Skor Diskriminan LDA (Linier via Sigma_pool^-1) & QDA (Kuadratik via Mahalanobis per kelas)\ninv_pool = np.linalg.inv(Sigma_pool)\nlda_scores = np.column_stack([\n    X_te @ (inv_pool @ means[k]) - 0.5 * (means[k] @ inv_pool @ means[k]) + np.log(priors[k])\n    for k in range(K)\n])\nqda_scores = np.zeros((len(X_te), K))\nfor k in range(K):\n    sign, logdet = np.linalg.slogdet(covs[k])\n    diff = X_te - means[k]\n    mahal_sq = np.sum(diff * np.linalg.solve(covs[k], diff.T).T, axis=1)\n    qda_scores[:, k] = -0.5 * logdet - 0.5 * mahal_sq + np.log(priors[k])\n\n# 3. Proyeksi Diskriminatif Fisher: maksimalkan |W^T S_B W| / |W^T S_W W|\nmu_global = X_tr.mean(axis=0)\nS_B = sum(np.sum(y_tr == k) * np.outer(means[k] - mu_global, means[k] - mu_global) for k in range(K))\n# Selesaikan generalized symmetric eigenproblem S_B v = lambda S_W v\neigvals, eigvecs = eigh(S_B, S_W)\norder = np.argsort(eigvals)[::-1]\neigvals = np.maximum(eigvals[order], 0.0)\neigvecs = eigvecs[:, order]\nexplained = eigvals / eigvals.sum()\n\n# Bandingkan jarak Euclidean vs Mahalanobis untuk titik uji ekstrem terhadap sentroid kelas 0\nx_probe = np.array([2.0, 2.0, 0.0, 0.0])  # searah korelasi positif kelas 0\nd_euc_0 = float(np.linalg.norm(x_probe - means[0]))\nd_mah_0 = float(np.sqrt((x_probe - means[0]) @ np.linalg.solve(covs[0], x_probe - means[0])))\nx_ortho = np.array([2.0, -2.0, 0.0, 0.0])  # tegak lurus korelasi positif kelas 0\nd_euc_o = float(np.linalg.norm(x_ortho - means[0]))\nd_mah_o = float(np.sqrt((x_ortho - means[0]) @ np.linalg.solve(covs[0], x_ortho - means[0])))\n\nprint(\"=== First-Principles LDA, QDA & Fisher Discriminant Projection (K=3, d=4) ===\")\nprint(f\"Akurasi Uji -> LDA (Linear Pooled) : {np.mean(np.argmax(lda_scores, axis=1) == y_te)*100:.2f}%\")\nprint(f\"Akurasi Uji -> QDA (Quadratic Full): {np.mean(np.argmax(qda_scores, axis=1) == y_te)*100:.2f}%\")\nprint(f\"Eigenvalues S_W^-1 S_B (Max rank = K-1 = 2): {np.round(eigvals, 5).tolist()}\")\nprint(f\"Proporsi Daya Pisah Fisher (LD1, LD2)      : {explained[0]*100:.2f}%, {explained[1]*100:.2f}% (LD3+LD4 = {(explained[2]+explained[3])*100:.4f}%)\")\nprint(\"=== Intuisi Geometri Jarak Euclidean vs Mahalanobis (Kelas 0 berkorelasi +0.75) ===\")\nprint(f\"Titik [2, +2, 0, 0] (searah elips) -> Euclidean: {d_euc_0:.3f} | Mahalanobis: {d_mah_0:.3f}\")\nprint(f\"Titik [2, -2, 0, 0] (lawan elips)  -> Euclidean: {d_euc_o:.3f} | Mahalanobis: {d_mah_o:.3f}\")",
          "expectedOutput": "=== First-Principles LDA, QDA & Fisher Discriminant Projection (K=3, d=4) ===\nAkurasi Uji -> LDA (Linear Pooled) : 82.83%\nAkurasi Uji -> QDA (Quadratic Full): 86.50%\nEigenvalues S_W^-1 S_B (Max rank = K-1 = 2): [2.30262, 0.34875, 0.0, 0.0]\nProporsi Daya Pisah Fisher (LD1, LD2)      : 86.85%, 13.15% (LD3+LD4 = 0.0000%)\n=== Intuisi Geometri Jarak Euclidean vs Mahalanobis (Kelas 0 berkorelasi +0.75) ===\nTitik [2, +2, 0, 0] (searah elips) -> Euclidean: 2.572 | Mahalanobis: 1.396\nTitik [2, -2, 0, 0] (lawan elips)  -> Euclidean: 2.788 | Mahalanobis: 4.170",
          "actualOutput": "=== First-Principles LDA, QDA & Fisher Discriminant Projection (K=3, d=4) ===\nAkurasi Uji -> LDA (Linear Pooled) : 82.83%\nAkurasi Uji -> QDA (Quadratic Full): 86.50%\nEigenvalues S_W^-1 S_B (Max rank = K-1 = 2): [2.30262, 0.34875, 0.0, 0.0]\nProporsi Daya Pisah Fisher (LD1, LD2)      : 86.85%, 13.15% (LD3+LD4 = 0.0000%)\n=== Intuisi Geometri Jarak Euclidean vs Mahalanobis (Kelas 0 berkorelasi +0.75) ===\nTitik [2, +2, 0, 0] (searah elips) -> Euclidean: 2.572 | Mahalanobis: 1.396\nTitik [2, -2, 0, 0] (lawan elips)  -> Euclidean: 2.788 | Mahalanobis: 4.170",
