          "filename": "10_2_sklearn_lda_vs_qda_scaling.py",
          "code": "import numpy as np\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis, QuadraticDiscriminantAnalysis\nfrom sklearn.metrics import accuracy_score\n\nrng = np.random.default_rng(303)\n\n# Skenario A: Kovarians heterogen ekstrem (mean identik = 0, beda skala & rotasi elips!)\nn_tr, n_te = 400, 1000\ncov_a0 = np.array([[4.0, 2.8], [2.8, 2.5]])\ncov_a1 = np.array([[0.8, -0.55], [-0.55, 0.8]])\ny_a_tr = rng.integers(0, 2, size=n_tr)\ny_a_te = rng.integers(0, 2, size=n_te)\nX_a_tr = np.where(y_a_tr[:, None] == 0, rng.multivariate_normal([0, 0], cov_a0, n_tr),\n                  rng.multivariate_normal([0, 0], cov_a1, n_tr))\nX_a_te = np.where(y_a_te[:, None] == 0, rng.multivariate_normal([0, 0], cov_a0, n_te),\n                  rng.multivariate_normal([0, 0], cov_a1, n_te))\n\nlda_a = LinearDiscriminantAnalysis().fit(X_a_tr, y_a_tr)\nqda_a = QuadraticDiscriminantAnalysis().fit(X_a_tr, y_a_tr)\n\nprint(\"=== Skenario A: Mean Sama (mu0 = mu1 = 0), Kovarians Berbeda Tajam ===\")\nprint(f\"LDA (Linear)    Test Accuracy: {accuracy_score(y_a_te, lda_a.predict(X_a_te))*100:.2f}% (buta terhadap selisih kovarians!)\")\nprint(f\"QDA (Quadratic) Test Accuracy: {accuracy_score(y_a_te, qda_a.predict(X_a_te))*100:.2f}% (menangkap batas eliptik kuadratik)\")\n\n# Skenario B: Ledakan Parameter QDA O(K d^2) saat dimensi d naik pada n_per_class = 70\nprint(\"=== Skenario B: Ledakan Varians QDA vs LDA & Regularized QDA (n_k=70, K=3) ===\")\nprint(\"Dim d | Param Cov LDA | Param Cov QDA | LDA Acc | QDA(reg=0) | QDA(reg=0.25)\")\nprint(\"-\" * 76)\nfor d in [4, 12, 25, 45]:\n    # Homoskedastik ringan + sedikit beda kovarians\n    idx = np.arange(d)\n    base_cov = 0.5 ** np.abs(idx[:, None] - idx[None, :])\n    Xtr_l, ytr_l, Xte_l, yte_l = [], [], [], []\n    for k in range(3):\n        mu_k = np.zeros(d)\n        mu_k[k % d] = 1.6\n        mu_k[(k + 1) % d] = -1.0\n        cov_k = base_cov * (1.0 + 0.15 * k)\n        Xtr_l.append(rng.multivariate_normal(mu_k, cov_k, size=70))\n        ytr_l.append(np.full(70, k))\n        Xte_l.append(rng.multivariate_normal(mu_k, cov_k, size=200))\n        yte_l.append(np.full(200, k))\n    Xtr_b, ytr_b = np.vstack(Xtr_l), np.concatenate(ytr_l)\n    Xte_b, yte_b = np.vstack(Xte_l), np.concatenate(yte_l)\n\n    acc_lda = accuracy_score(yte_b, LinearDiscriminantAnalysis().fit(Xtr_b, ytr_b).predict(Xte_b))\n    acc_qda0 = accuracy_score(yte_b, QuadraticDiscriminantAnalysis(reg_param=0.0).fit(Xtr_b, ytr_b).predict(Xte_b))\n    acc_qdar = accuracy_score(yte_b, QuadraticDiscriminantAnalysis(reg_param=0.25).fit(Xtr_b, ytr_b).predict(Xte_b))\n    p_lda = d * (d + 1) // 2\n    p_qda = 3 * p_lda\n    print(f\"{d:5d} | {p_lda:13d} | {p_qda:13d} | {acc_lda*100:6.2f}% | {acc_qda0*100:9.2f}% | {acc_qdar*100:12.2f}%\")",
          "expectedOutput": "=== Skenario A: Mean Sama (mu0 = mu1 = 0), Kovarians Berbeda Tajam ===\nLDA (Linear)    Test Accuracy: 65.00% (buta terhadap selisih kovarians!)\nQDA (Quadratic) Test Accuracy: 84.50% (menangkap batas eliptik kuadratik)\n=== Skenario B: Ledakan Varians QDA vs LDA & Regularized QDA (n_k=70, K=3) ===\nDim d | Param Cov LDA | Param Cov QDA | LDA Acc | QDA(reg=0) | QDA(reg=0.25)\n----------------------------------------------------------------------------\n    4 |            10 |            30 |  96.50% |     96.50% |        96.33%\n   12 |            78 |           234 |  95.17% |     94.50% |        94.33%\n   25 |           325 |           975 |  94.33% |     85.00% |        93.50%\n   45 |          1035 |          3105 |  90.00% |     69.33% |        83.00%",
          "actualOutput": "=== Skenario A: Mean Sama (mu0 = mu1 = 0), Kovarians Berbeda Tajam ===\nLDA (Linear)    Test Accuracy: 65.00% (buta terhadap selisih kovarians!)\nQDA (Quadratic) Test Accuracy: 84.50% (menangkap batas eliptik kuadratik)\n=== Skenario B: Ledakan Varians QDA vs LDA & Regularized QDA (n_k=70, K=3) ===\nDim d | Param Cov LDA | Param Cov QDA | LDA Acc | QDA(reg=0) | QDA(reg=0.25)\n----------------------------------------------------------------------------\n    4 |            10 |            30 |  96.50% |     96.50% |        96.33%\n   12 |            78 |           234 |  95.17% |     94.50% |        94.33%\n   25 |           325 |           975 |  94.33% |     85.00% |        93.50%\n   45 |          1035 |          3105 |  90.00% |     69.33% |        83.00%",
