          "id": "code-ml-10-2-ch10_2_diag",
          "title": "Audit Produksi: Fisher LDA vs PCA pada Derau Varians Besar & Condition Number",
          "language": "python",
          "filename": "10_2_fisher_vs_pca_condition_audit.py",
          "code": "import numpy as np\nfrom sklearn.decomposition import PCA\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(404)\n\n# Bangkitkan 3 kelas di R^10: 2 sumbu diskriminan bervarians KECIL, 8 sumbu derau bervarians BESAR\nn_per = 180\ny_all = np.repeat([0, 1, 2], n_per)\nX_all = np.zeros((3 * n_per, 10))\n# 2 dimensi sinyal diskriminan (varians 0.5, pusat berjarak 1.4)\ncenters = np.array([[0.0, 0.0], [1.4, 0.9], [0.2, -1.5]])\nfor k in range(3):\n    sl = slice(k * n_per, (k + 1) * n_per)\n    X_all[sl, :2] = centers[k] + rng.normal(0.0, 0.55, size=(n_per, 2))\n# 8 dimensi pengganggu bervarians 6x lebih besar (menjebak PCA unsupervised!)\nX_all[:, 2:] = rng.normal(0.0, 3.2, size=(3 * n_per, 8))\n# Rotasi ortogonal acak agar sumbu sinyal tidak sejajar koordinat asli\nQ, _ = np.linalg.qr(rng.normal(size=(10, 10)))\nX_rot = X_all @ Q\n\n# Split train/test terstratifikasi\nidx_tr, idx_te = [], []\nfor k in range(3):\n    base = k * n_per\n    idx_tr.extend(range(base, base + 120))\n    idx_te.extend(range(base + 120, base + n_per))\nX_tr, y_tr = X_rot[idx_tr], y_all[idx_tr]\nX_te, y_te = X_rot[idx_te], y_all[idx_te]\n\n# Bandingkan reduksi dimensi 10D -> 2D: PCA (unsupervised) vs Fisher LDA (supervised, max K-1=2)\npca = PCA(n_components=2).fit(X_tr)\nlda = LinearDiscriminantAnalysis(n_components=2).fit(X_tr, y_tr)\n\nZ_pca_tr, Z_pca_te = pca.transform(X_tr), pca.transform(X_te)\nZ_lda_tr, Z_lda_te = lda.transform(X_tr), lda.transform(X_te)\n\ndef fisher_separation_ratio(Z: np.ndarray, y: np.ndarray) -> float:\n    mu = Z.mean(axis=0)\n    sb, sw = 0.0, 0.0\n    for k in np.unique(y):\n        Zk = Z[y == k]\n        muk = Zk.mean(axis=0)\n        sb += len(Zk) * float(np.sum((muk - mu) ** 2))\n        sw += float(np.sum((Zk - muk) ** 2))\n    return sb / max(sw, 1e-12)\n\nacc_pca_lr = accuracy_score(y_te, LogisticRegression().fit(Z_pca_tr, y_tr).predict(Z_pca_te))\nacc_lda_lr = accuracy_score(y_te, LogisticRegression().fit(Z_lda_tr, y_tr).predict(Z_lda_te))\n\n# Audit bilangan kondisi matriks kovarians per kelas pada data imbalanced\ncov_maj = np.cov(rng.normal(size=(500, 30)), rowvar=False)\ncov_min = np.cov(rng.normal(size=(35, 30)), rowvar=False)\n\nprint(\"=== Audit Proyeksi 10D -> 2D: PCA (Unsupervised) vs Fisher LDA (Supervised) ===\")\nprint(f\"PCA (2 komponen)        -> Test Fisher Ratio: {fisher_separation_ratio(Z_pca_te, y_te):.4f} | Downstream LogReg Acc: {acc_pca_lr*100:.2f}%\")\nprint(f\"Fisher LDA (K-1=2 komp) -> Test Fisher Ratio: {fisher_separation_ratio(Z_lda_te, y_te):.4f} | Downstream LogReg Acc: {acc_lda_lr*100:.2f}%\")\nprint(f\"Rasio Varians Diskriminan LDA (LD1, LD2)    : {[round(float(v), 4) for v in lda.explained_variance_ratio_]}\")\nprint(\"=== Audit Condition Number Kovarians QDA pada Kelas Imbalanced (d=30) ===\")\nprint(f\"Kelas Mayoritas (n=500, d=30) -> cond(Sigma_hat): {np.linalg.cond(cov_maj):10.2f}\")\nprint(f\"Kelas Minoritas (n=35,  d=30) -> cond(Sigma_hat): {np.linalg.cond(cov_min):10.2f} (meledak -> QDA tidak stabil!)\")",
          "expectedOutput": "=== Audit Proyeksi 10D -> 2D: PCA (Unsupervised) vs Fisher LDA (Supervised) ===\nPCA (2 komponen)        -> Test Fisher Ratio: 0.0012 | Downstream LogReg Acc: 30.56%\nFisher LDA (K-1=2 komp) -> Test Fisher Ratio: 2.0552 | Downstream LogReg Acc: 88.89%\nRasio Varians Diskriminan LDA (LD1, LD2)    : [0.8578, 0.1422]\n=== Audit Condition Number Kovarians QDA pada Kelas Imbalanced (d=30) ===\nKelas Mayoritas (n=500, d=30) -> cond(Sigma_hat):       2.67\nKelas Minoritas (n=35,  d=30) -> cond(Sigma_hat):     229.42 (meledak -> QDA tidak stabil!)",
          "actualOutput": "=== Audit Proyeksi 10D -> 2D: PCA (Unsupervised) vs Fisher LDA (Supervised) ===\nPCA (2 komponen)        -> Test Fisher Ratio: 0.0012 | Downstream LogReg Acc: 30.56%\nFisher LDA (K-1=2 komp) -> Test Fisher Ratio: 2.0552 | Downstream LogReg Acc: 88.89%\nRasio Varians Diskriminan LDA (LD1, LD2)    : [0.8578, 0.1422]\n=== Audit Condition Number Kovarians QDA pada Kelas Imbalanced (d=30) ===\nKelas Mayoritas (n=500, d=30) -> cond(Sigma_hat):       2.67\nKelas Minoritas (n=35,  d=30) -> cond(Sigma_hat):     229.42 (meledak -> QDA tidak stabil!)",
