          "id": "code-ml-10-3-ch10_3_scratch",
          "title": "First-Principles NumPy: Ledoit-Wolf & OAS Shrinkage vs Marchenko-Pastur",
          "language": "python",
          "filename": "10_3_ledoit_wolf_oas_scratch.py",
          "code": "import numpy as np\n\ndef ledoit_wolf_shrinkage(X_centered: np.ndarray) -> tuple[np.ndarray, float]:\n    \"\"\"First-principles Ledoit-Wolf (2004) analytical shrinkage menuju target isotropik mu*I.\"\"\"\n    n, d = X_centered.shape\n    S = (X_centered.T @ X_centered) / n\n    mu = float(np.trace(S) / d)\n    # Jarak kuadrat Frobenius dari S ke target mu*I: delta^2 = ||S - mu*I||_F^2 / d\n    diff_target = S - mu * np.eye(d)\n    delta_sq = float(np.sum(diff_target ** 2) / d)\n    # Estimasi varians asimtotik beta^2 = (1/n^2) sum_i ||x_i x_i^T - S||_F^2 / d\n    sq_norms = np.sum(X_centered ** 2, axis=1)\n    # ||x_i x_i^T - S||_F^2 = ||x_i||^4 - 2 x_i^T S x_i + ||S||_F^2\n    term1 = float(np.mean(sq_norms ** 2))\n    term2 = float(np.sum(S ** 2))\n    beta_sq_bar = max(0.0, (term1 - term2) / (n * d))\n    beta_sq = min(beta_sq_bar, delta_sq)\n    shrink = 1.0 if delta_sq < 1e-12 else float(beta_sq / delta_sq)\n    Sigma_lw = (1.0 - shrink) * S + shrink * mu * np.eye(d)\n    return Sigma_lw, shrink\n\ndef oas_shrinkage(X_centered: np.ndarray) -> tuple[np.ndarray, float]:\n    \"\"\"First-principles Oracle Approximating Shrinkage (OAS) dibawah asumsi Gaussian.\"\"\"\n    n, d = X_centered.shape\n    S = (X_centered.T @ X_centered) / n\n    tr_S = float(np.trace(S))\n    tr_S2 = float(np.sum(S ** 2))\n    mu = tr_S / d\n    num = (1.0 - 2.0 / d) * tr_S2 + tr_S ** 2\n    den = (n + 1.0 - 2.0 / d) * (tr_S2 - (tr_S ** 2) / d)\n    rho = 1.0 if den <= 1e-12 else float(np.clip(num / den, 0.0, 1.0))\n    Sigma_oas = (1.0 - rho) * S + rho * mu * np.eye(d)\n    return Sigma_oas, rho\n\nrng = np.random.default_rng(505)\nd = 80\nidx = np.arange(d)\nSigma_true = 0.65 ** np.abs(idx[:, None] - idx[None, :])\ntrue_cond = float(np.linalg.cond(Sigma_true))\n\nprint(f\"=== Distorsi Spektral Marchenko-Pastur & Pemulihan Ledoit-Wolf / OAS (d={d}, true cond={true_cond:.1f}) ===\")\nprint(\"n   | d/n  | Sample cond  | LW delta | OAS rho | ||S-Sig||_F | ||LW-Sig||_F | ||OAS-Sig||_F\")\nprint(\"-\" * 92)\nfor n in [400, 120, 85, 60]:\n    X = rng.multivariate_normal(np.zeros(d), Sigma_true, size=n)\n    Xc = X - X.mean(axis=0)\n    S_emp = (Xc.T @ Xc) / n\n    S_lw, delta_lw = ledoit_wolf_shrinkage(Xc)\n    S_oas, rho_oas = oas_shrinkage(Xc)\n\n    eigs = np.linalg.eigvalsh(S_emp)\n    cond_str = \"SINGULAR\" if eigs[0] < 1e-10 else f\"{eigs[-1]/eigs[0]:12.1f}\"\n    err_emp = float(np.linalg.norm(S_emp - Sigma_true, \"fro\"))\n    err_lw = float(np.linalg.norm(S_lw - Sigma_true, \"fro\"))\n    err_oas = float(np.linalg.norm(S_oas - Sigma_true, \"fro\"))\n    print(f\"{n:3d} | {d/n:4.2f} | {cond_str:>12s} | {delta_lw:8.4f} | {rho_oas:7.4f} | {err_emp:11.3f} | {err_lw:12.3f} | {err_oas:13.3f}\")",
          "expectedOutput": "=== Distorsi Spektral Marchenko-Pastur & Pemulihan Ledoit-Wolf / OAS (d=80, true cond=22.1) ===\nn   | d/n  | Sample cond  | LW delta | OAS rho | ||S-Sig||_F | ||LW-Sig||_F | ||OAS-Sig||_F\n--------------------------------------------------------------------------------------------\n400 | 0.20 |         54.8 |   0.1261 |  0.1261 |       3.954 |        3.704 |         3.704\n120 | 0.67 |        531.5 |   0.2933 |  0.2955 |       7.819 |        6.374 |         6.371\n 85 | 0.94 |      59626.9 |   0.3861 |  0.3892 |       8.824 |        6.805 |         6.803\n 60 | 1.33 |     SINGULAR |   0.5088 |  0.5177 |       9.745 |        7.333 |         7.348",
          "actualOutput": "=== Distorsi Spektral Marchenko-Pastur & Pemulihan Ledoit-Wolf / OAS (d=80, true cond=22.1) ===\nn   | d/n  | Sample cond  | LW delta | OAS rho | ||S-Sig||_F | ||LW-Sig||_F | ||OAS-Sig||_F\n--------------------------------------------------------------------------------------------\n400 | 0.20 |         54.8 |   0.1261 |  0.1261 |       3.954 |        3.704 |         3.704\n120 | 0.67 |        531.5 |   0.2933 |  0.2955 |       7.819 |        6.374 |         6.371\n 85 | 0.94 |      59626.9 |   0.3861 |  0.3892 |       8.824 |        6.805 |         6.803\n 60 | 1.33 |     SINGULAR |   0.5088 |  0.5177 |       9.745 |        7.333 |         7.348",
