          "filename": "10_3_sklearn_highdim_shrinkage_benchmark.py",
          "code": "import numpy as np\nfrom sklearn.covariance import OAS\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis, QuadraticDiscriminantAnalysis\nfrom sklearn.metrics import accuracy_score, roc_auc_score\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(606)\n# Rezim p > n (high-dimensional biomarker / EEG): n_train = 110, d = 160 berkorelasi blok AR(1)\nn_tr, n_te, d = 110, 600, 160\nidx = np.arange(d)\nSigma = 0.78 ** np.abs(idx[:, None] - idx[None, :])\n# Sinyal kontras terstruktur pada 24 fitur pertama yang berkorelasi erat\nmu0 = np.zeros(d)\nmu1 = np.zeros(d)\nmu1[:24] = 0.42 * np.where(np.arange(24) % 2 == 0, 1.0, -0.75)\n\ndef sample_highdim(n: int):\n    y = rng.binomial(1, 0.5, size=n)\n    X = np.zeros((n, d))\n    n1 = int(y.sum())\n    X[y == 0] = rng.multivariate_normal(mu0, Sigma, size=n - n1)\n    X[y == 1] = rng.multivariate_normal(mu1, Sigma, size=n1)\n    return X, y\n\nX_tr, y_tr = sample_highdim(n_tr)\nX_te, y_te = sample_highdim(n_te)\n\nmodels = [\n    (\"LDA Default (solver='svd', no shrink)\", Pipeline([(\"sc\", StandardScaler()), (\"clf\", LinearDiscriminantAnalysis(solver=\"svd\"))])),\n    (\"QDA Default (unregularized, p > n)   \", Pipeline([(\"sc\", StandardScaler()), (\"clf\", QuadraticDiscriminantAnalysis())])),\n    (\"Shrinkage QDA (eigen + Ledoit-Wolf)  \", Pipeline([(\"sc\", StandardScaler()), (\"clf\", QuadraticDiscriminantAnalysis(solver=\"eigen\", shrinkage=\"auto\"))])),\n    (\"Shrinkage LDA (lsqr + Ledoit-Wolf)   \", Pipeline([(\"sc\", StandardScaler()), (\"clf\", LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=\"auto\"))])),\n    (\"Shrinkage LDA (lsqr + OAS)           \", Pipeline([(\"sc\", StandardScaler()), (\"clf\", LinearDiscriminantAnalysis(solver=\"lsqr\", covariance_estimator=OAS()))])),\n]\n\nprint(f\"=== Benchmark Rezim Singuler p > n (n_train={n_tr}, d={d}, n_test={n_te}) ===\")\nprint(\"Model                                 | Train Acc | Test Acc | Test ROC-AUC\")\nprint(\"-\" * 77)\nfor name, pipe in models:\n    try:\n        pipe.fit(X_tr, y_tr)\n        tr_acc = accuracy_score(y_tr, pipe.predict(X_tr))\n        te_acc = accuracy_score(y_te, pipe.predict(X_te))\n        te_auc = roc_auc_score(y_te, pipe.predict_proba(X_te)[:, 1])\n        print(f\"{name:37s} | {tr_acc*100:8.2f}% | {te_acc*100:7.2f}% | {te_auc:12.4f}\")\n    except np.linalg.LinAlgError:\n        print(f\"{name:37s} |  SINGULAR |  CRASH!  |  LinAlgError\")",
          "expectedOutput": "=== Benchmark Rezim Singuler p > n (n_train=110, d=160, n_test=600) ===\nModel                                 | Train Acc | Test Acc | Test ROC-AUC\n-----------------------------------------------------------------------------\nLDA Default (solver='svd', no shrink) |   100.00% |   70.83% |       0.7883\nQDA Default (unregularized, p > n)    |  SINGULAR |  CRASH!  |  LinAlgError\nShrinkage QDA (eigen + Ledoit-Wolf)   |   100.00% |   62.17% |       0.6732\nShrinkage LDA (lsqr + Ledoit-Wolf)    |   100.00% |   86.00% |       0.9471\nShrinkage LDA (lsqr + OAS)            |   100.00% |   86.33% |       0.9445",
          "actualOutput": "=== Benchmark Rezim Singuler p > n (n_train=110, d=160, n_test=600) ===\nModel                                 | Train Acc | Test Acc | Test ROC-AUC\n-----------------------------------------------------------------------------\nLDA Default (solver='svd', no shrink) |   100.00% |   70.83% |       0.7883\nQDA Default (unregularized, p > n)    |  SINGULAR |  CRASH!  |  LinAlgError\nShrinkage QDA (eigen + Ledoit-Wolf)   |   100.00% |   62.17% |       0.6732\nShrinkage LDA (lsqr + Ledoit-Wolf)    |   100.00% |   86.00% |       0.9471\nShrinkage LDA (lsqr + OAS)            |   100.00% |   86.33% |       0.9445",
