          "id": "code-ml-10-3-ch10_3_diag",
          "title": "Audit Produksi: Bahaya Tanpa StandardScaler pada Target mu*I & Kurva delta",
          "language": "python",
          "filename": "10_3_scaling_shrinkage_sensitivity_audit.py",
          "code": "import numpy as np\nfrom sklearn.covariance import OAS\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(707)\n# Audit kritis perilaku internal sklearn._cov:\n# - shrinkage=\"auto\" menstandarisasi internal sebelum Ledoit-Wolf (invarian skala)\n# - covariance_estimator=OAS() & shrinkage=float TIDAK menstandarisasi -> hancur tanpa StandardScaler!\nn_tr, n_te, d = 100, 600, 80\nidx = np.arange(d)\nSigma = 0.85 ** np.abs(idx[:, None] - idx[None, :])\nmu1 = np.zeros(d)\nmu1[:8] = np.where(np.arange(8) % 2 == 0, 0.45, -0.45)\n\ndef make_hetero_scale(n: int):\n    y = rng.binomial(1, 0.5, size=n)\n    X = np.zeros((n, d))\n    n1 = int(y.sum())\n    X[y == 0] = rng.multivariate_normal(np.zeros(d), Sigma, size=n - n1)\n    X[y == 1] = rng.multivariate_normal(mu1, Sigma, size=n1)\n    # 5 fitur DERAU terakhir berskala 500x lebih besar (misal pendapatan ribuan rupiah)\n    X[:, -5:] *= 500.0\n    return X, y\n\nX_tr, y_tr = make_hetero_scale(n_tr)\nX_te, y_te = make_hetero_scale(n_te)\n\nconfigs = [\n    (\"LDA(covariance_estimator=OAS()) TANPA Scaler  \", LinearDiscriminantAnalysis(solver=\"lsqr\", covariance_estimator=OAS())),\n    (\"Pipeline(StandardScaler + OAS())              \", Pipeline([(\"sc\", StandardScaler()), (\"lda\", LinearDiscriminantAnalysis(solver=\"lsqr\", covariance_estimator=OAS()))])),\n    (\"LDA(shrinkage=0.20) TANPA Scaler              \", LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=0.20)),\n    (\"Pipeline(StandardScaler + shrinkage=0.20)     \", Pipeline([(\"sc\", StandardScaler()), (\"lda\", LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=0.20))])),\n    (\"LDA(shrinkage='auto') (internal StandardScale)\", LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=\"auto\")),\n]\n\nprint(\"=== Audit Skala Fitur Heterogen (5 Fitur Derau 500x) pada Target Isotropik mu*I ===\")\nfor label, mdl in configs:\n    mdl.fit(X_tr, y_tr)\n    print(f\"{label} -> Test Acc: {accuracy_score(y_te, mdl.predict(X_te))*100:6.2f}%\")\n\n# Kurva sensitivitas intensitas shrinkage manual delta in [0.01, 1.0] pada data terstandarisasi\nsc = StandardScaler().fit(X_tr)\nXs_tr, Xs_te = sc.transform(X_tr), sc.transform(X_te)\nS_pool = np.cov(np.vstack([Xs_tr[y_tr == 0] - Xs_tr[y_tr == 0].mean(0),\n                           Xs_tr[y_tr == 1] - Xs_tr[y_tr == 1].mean(0)]), rowvar=False)\nmu_tr = float(np.trace(S_pool) / d)\n\nprint(\"=== Kurva Sensitivitas Shrinkage delta terhadap Condition Number & Test Accuracy ===\")\nprint(\"delta  | cond(Sigma_delta) | Test Acc\")\nprint(\"-\" * 39)\nfor delta in [0.01, 0.05, 0.15, 0.30, 0.50, 0.80, 1.00]:\n    S_d = (1.0 - delta) * S_pool + delta * mu_tr * np.eye(d)\n    clf = LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=delta).fit(Xs_tr, y_tr)\n    print(f\"{delta:6.2f} | {np.linalg.cond(S_d):17.2f} | {accuracy_score(y_te, clf.predict(Xs_te))*100:7.2f}%\")",
          "expectedOutput": "=== Audit Skala Fitur Heterogen (5 Fitur Derau 500x) pada Target Isotropik mu*I ===\nLDA(covariance_estimator=OAS()) TANPA Scaler   -> Test Acc:  51.50%\nPipeline(StandardScaler + OAS())               -> Test Acc:  83.50%\nLDA(shrinkage=0.20) TANPA Scaler               -> Test Acc:  51.83%\nPipeline(StandardScaler + shrinkage=0.20)      -> Test Acc:  85.50%\nLDA(shrinkage='auto') (internal StandardScale) -> Test Acc:  83.67%\n=== Kurva Sensitivitas Shrinkage delta terhadap Condition Number & Test Accuracy ===\ndelta  | cond(Sigma_delta) | Test Acc\n---------------------------------------\n  0.01 |           1234.35 |   91.33%\n  0.05 |            266.71 |   92.17%\n  0.15 |             81.90 |   87.67%\n  0.30 |             34.49 |   81.17%\n  0.50 |             15.38 |   70.67%\n  0.80 |              4.60 |   60.50%\n  1.00 |              1.00 |   55.17%",
