          "id": "code-ml-10-4-ch10_4_scratch",
          "title": "First-Principles NumPy: Paradoks Double-Counting & Zero-Frequency Collapse",
          "language": "python",
          "filename": "10_4_nb_double_counting_lidstone_scratch.py",
          "code": "import numpy as np\nfrom scipy.special import logsumexp\nfrom sklearn.metrics import brier_score_loss, roc_auc_score\n\ndef expected_calibration_error(y_true: np.ndarray, p_pred: np.ndarray, n_bins: int = 10) -> float:\n    bins = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    n = len(y_true)\n    for lo, hi in zip(bins[:-1], bins[1:]):\n        mask = (p_pred >= lo) & (p_pred <= hi if hi == 1.0 else p_pred < hi)\n        if np.any(mask):\n            ece += (np.sum(mask) / n) * abs(float(np.mean(y_true[mask])) - float(np.mean(p_pred[mask])))\n    return float(ece)\n\n# Bagian 1: Demonstrasi Double-Counting Evidence pada GaussianNB (m fitur berkorelasi rho=0.92)\nrng = np.random.default_rng(808)\nn_tr, n_te = 800, 2000\n\nprint(\"=== Bagian 1: Paradoks Double-Counting GaussianNB (Korelasi Antar-Fitur rho=0.92) ===\")\nprint(\"m_feat | ROC-AUC | Brier Score |  ECE   | % Pred Ekstrem (<0.05 atau >0.95)\")\nprint(\"-\" * 74)\nfor m in [1, 3, 8, 16]:\n    cov = np.full((m, m), 0.92)\n    np.fill_diagonal(cov, 1.0)\n    mu0 = np.zeros(m)\n    mu1 = np.full(m, 0.95)\n\n    y_tr = rng.binomial(1, 0.5, size=n_tr)\n    y_te = rng.binomial(1, 0.5, size=n_te)\n    X_tr = np.where(y_tr[:, None] == 1, rng.multivariate_normal(mu1, cov, n_tr),\n                    rng.multivariate_normal(mu0, cov, n_tr))\n    X_te = np.where(y_te[:, None] == 1, rng.multivariate_normal(mu1, cov, n_te),\n                    rng.multivariate_normal(mu0, cov, n_te))\n\n    # First-principles GaussianNB (log-space)\n    log_p = np.zeros((n_te, 2))\n    for k in [0, 1]:\n        Xk = X_tr[y_tr == k]\n        mu_k, var_k = Xk.mean(axis=0), Xk.var(axis=0) + 1e-9\n        log_p[:, k] = np.log(len(Xk) / n_tr) - 0.5 * np.sum(\n            np.log(2.0 * np.pi * var_k) + ((X_te - mu_k) ** 2) / var_k, axis=1\n        )\n    p1 = np.exp(log_p[:, 1] - logsumexp(log_p, axis=1))\n    auc = roc_auc_score(y_te, p1)\n    brier = brier_score_loss(y_te, p1)\n    ece = expected_calibration_error(y_te, p1)\n    extreme_pct = float(np.mean((p1 < 0.05) | (p1 > 0.95)) * 100.0)\n    print(f\"{m:6d} | {auc:7.4f} | {brier:11.4f} | {ece:6.4f} | {extreme_pct:31.2f}%\")\n\n# Bagian 2: Zero-Frequency Collapse pada MultinomialNB tanpa Lidstone Smoothing (alpha=0 vs alpha>0)\n# Vocab: [\"gratis\", \"promo\", \"tagihan\", \"rapat\", \"kripto\"]\ncounts_ham = np.array([2, 4, 40, 54, 0], dtype=float)   # \"kripto\" tidak pernah muncul di ham!\ncounts_spam = np.array([45, 38, 5, 2, 10], dtype=float)\ndoc_test = np.array([0, 0, 2, 3, 1], dtype=float)       # 2x tagihan, 3x rapat, 1x kripto (jelas ham!)\n\nprint(\"=== Bagian 2: Zero-Frequency Collapse MultinomialNB pada Dokumen Uji [0, 0, 2, 3, 1] ===\")\nfor alpha in [0.0, 0.01, 0.5, 1.0]:\n    V = len(counts_ham)\n    if alpha == 0.0:\n        th_ham = counts_ham / counts_ham.sum()\n        th_spam = counts_spam / counts_spam.sum()\n        # Produk langsung likelihood (rentan nol mutlak)\n        p_ham_un = 0.5 * float(np.prod(th_ham ** doc_test))\n        p_spam_un = 0.5 * float(np.prod(th_spam ** doc_test))\n        p_spam = p_spam_un / (p_ham_un + p_spam_un)\n    else:\n        th_ham = (counts_ham + alpha) / (counts_ham.sum() + alpha * V)\n        th_spam = (counts_spam + alpha) / (counts_spam.sum() + alpha * V)\n        lp_ham = np.log(0.5) + float(doc_test @ np.log(th_ham))\n        lp_spam = np.log(0.5) + float(doc_test @ np.log(th_spam))\n        p_spam = float(np.exp(lp_spam - logsumexp([lp_ham, lp_spam])))\n    print(f\"alpha = {alpha:4.2f} -> P(Spam | doc) = {p_spam:.6f} ({'COLLAPSE ke 1.0 karena 1 kata nol!' if alpha == 0 else 'Terkendali'})\")",
          "expectedOutput": "=== Bagian 1: Paradoks Double-Counting GaussianNB (Korelasi Antar-Fitur rho=0.92) ===\nm_feat | ROC-AUC | Brier Score |  ECE   | % Pred Ekstrem (<0.05 atau >0.95)\n--------------------------------------------------------------------------\n     1 |  0.7505 |      0.2026 | 0.0259 |                            0.55%\n     3 |  0.7673 |      0.2164 | 0.1295 |                           28.80%\n     8 |  0.7651 |      0.2570 | 0.2306 |                           69.60%\n    16 |  0.7492 |      0.2910 | 0.2833 |                           86.75%\n=== Bagian 2: Zero-Frequency Collapse MultinomialNB pada Dokumen Uji [0, 0, 2, 3, 1] ===\nalpha = 0.00 -> P(Spam | doc) = 1.000000 (COLLAPSE ke 1.0 karena 1 kata nol!)\nalpha = 0.01 -> P(Spam | doc) = 0.000808 (Terkendali)\nalpha = 0.50 -> P(Spam | doc) = 0.000037 (Terkendali)\nalpha = 1.00 -> P(Spam | doc) = 0.000038 (Terkendali)",
          "actualOutput": "=== Bagian 1: Paradoks Double-Counting GaussianNB (Korelasi Antar-Fitur rho=0.92) ===\nm_feat | ROC-AUC | Brier Score |  ECE   | % Pred Ekstrem (<0.05 atau >0.95)\n--------------------------------------------------------------------------\n     1 |  0.7505 |      0.2026 | 0.0259 |                            0.55%\n     3 |  0.7673 |      0.2164 | 0.1295 |                           28.80%\n     8 |  0.7651 |      0.2570 | 0.2306 |                           69.60%\n    16 |  0.7492 |      0.2910 | 0.2833 |                           86.75%\n=== Bagian 2: Zero-Frequency Collapse MultinomialNB pada Dokumen Uji [0, 0, 2, 3, 1] ===\nalpha = 0.00 -> P(Spam | doc) = 1.000000 (COLLAPSE ke 1.0 karena 1 kata nol!)\nalpha = 0.01 -> P(Spam | doc) = 0.000808 (Terkendali)\nalpha = 0.50 -> P(Spam | doc) = 0.000037 (Terkendali)\nalpha = 1.00 -> P(Spam | doc) = 0.000038 (Terkendali)",
