          "id": "code-ml-10-4-ch10_4_sklearn",
          "title": "Scikit-Learn: GaussianNB Mentah vs Platt/Isotonic di Bawah Biaya Elkan",
          "language": "python",
          "filename": "10_4_sklearn_nb_calibration_elkan_cost.py",
          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.naive_bayes import GaussianNB\n\ndef calc_ece(y_true: np.ndarray, p_pred: np.ndarray, n_bins: int = 10) -> float:\n    bins = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    for lo, hi in zip(bins[:-1], bins[1:]):\n        m = (p_pred >= lo) & (p_pred <= hi if hi == 1.0 else p_pred < hi)\n        if np.any(m):\n            ece += (np.sum(m) / len(y_true)) * abs(float(np.mean(y_true[m])) - float(np.mean(p_pred[m])))\n    return float(ece)\n\nrng = np.random.default_rng(909)\n# Data risiko transaksi dengan 14 fitur perilaku berkorelasi erat (prevalensi fraud 15%)\nd = 14\ncov = np.full((d, d), 0.84)\nnp.fill_diagonal(cov, 1.0)\nmu0 = np.zeros(d)\nmu1 = np.full(d, 0.90)\n\ndef sample_tx(n: int):\n    y = rng.binomial(1, 0.15, size=n)\n    X = np.zeros((n, d))\n    n1 = int(y.sum())\n    X[y == 0] = rng.multivariate_normal(mu0, cov, size=n - n1)\n    X[y == 1] = rng.multivariate_normal(mu1, cov, size=n1)\n    return X, y\n\nX_tr, y_tr = sample_tx(1500)\nX_te, y_te = sample_tx(2000)\n\n# Matriks biaya asimetris Elkan: FN (lolos fraud) = $500, FP (review manual) = $25\nC_FN, C_FP = 500.0, 25.0\ntau_elkan = C_FP / (C_FP + C_FN)  # 0.047619\n\nmodels = [\n    (\"GaussianNB Mentah (Uncalibrated)      \", GaussianNB()),\n    (\"Calibrated GNB (Platt / Sigmoid, cv=5)\", CalibratedClassifierCV(GaussianNB(), method=\"sigmoid\", cv=5)),\n    (\"Calibrated GNB (Isotonic, cv=5)       \", CalibratedClassifierCV(GaussianNB(), method=\"isotonic\", cv=5)),\n]\n\nprint(f\"=== Audit Kalibrasi & Biaya Elkan (C_FN=$500, C_FP=$25 -> tau*={tau_elkan:.4f}) ===\")\nprint(\"Model                                  | ROC-AUC |  Brier | LogLoss |   ECE  | Biaya Total ($)\")\nprint(\"-\" * 96)\nfor name, clf in models:\n    clf.fit(X_tr, y_tr)\n    p_te = clf.predict_proba(X_te)[:, 1]\n    y_hat = (p_te >= tau_elkan).astype(int)\n    fn = int(np.sum((y_te == 1) & (y_hat == 0)))\n    fp = int(np.sum((y_te == 0) & (y_hat == 1)))\n    total_cost = fn * C_FN + fp * C_FP\n    print(f\"{name:38s} | {roc_auc_score(y_te, p_te):7.4f} | {brier_score_loss(y_te, p_te):6.4f} | \"\n          f\"{log_loss(y_te, p_te):7.4f} | {calc_ece(y_te, p_te):6.4f} | {total_cost:15,.0f}\")",
          "expectedOutput": "=== Audit Kalibrasi & Biaya Elkan (C_FN=$500, C_FP=$25 -> tau*=0.0476) ===\nModel                                  | ROC-AUC |  Brier | LogLoss |   ECE  | Biaya Total ($)\n------------------------------------------------------------------------------------------------\nGaussianNB Mentah (Uncalibrated)       |  0.7358 | 0.2383 |  1.9227 | 0.2369 |          60,075\nCalibrated GNB (Platt / Sigmoid, cv=5) |  0.7358 | 0.1176 |  0.3867 | 0.0142 |          42,475\nCalibrated GNB (Isotonic, cv=5)        |  0.7361 | 0.1158 |  0.3822 | 0.0151 |          40,175",
          "actualOutput": "=== Audit Kalibrasi & Biaya Elkan (C_FN=$500, C_FP=$25 -> tau*=0.0476) ===\nModel                                  | ROC-AUC |  Brier | LogLoss |   ECE  | Biaya Total ($)\n------------------------------------------------------------------------------------------------\nGaussianNB Mentah (Uncalibrated)       |  0.7358 | 0.2383 |  1.9227 | 0.2369 |          60,075\nCalibrated GNB (Platt / Sigmoid, cv=5) |  0.7358 | 0.1176 |  0.3867 | 0.0142 |          42,475\nCalibrated GNB (Isotonic, cv=5)        |  0.7361 | 0.1158 |  0.3822 | 0.0151 |          40,175",
