          "id": "code-ml-10-4-ch10_4_diag",
          "title": "Audit Produksi: ComplementNB vs MultinomialNB Teks Timpang & partial_fit",
          "language": "python",
          "filename": "10_4_complement_nb_imbalanced_streaming.py",
          "code": "import numpy as np\nfrom sklearn.feature_extraction.text import TfidfTransformer\nfrom sklearn.metrics import f1_score, recall_score\nfrom sklearn.naive_bayes import ComplementNB, MultinomialNB\n\nrng = np.random.default_rng(1010)\n# Simulasi klasifikasi tiket teks TF-IDF (V=500 kata, 3 kelas SANGAT TIMPANG: 90% / 6% / 4%)\nV = 500\nbase_p = np.full(V, 1.0)\np0 = base_p.copy(); p0[:50] += 2.0; p0 /= p0.sum()\np1 = base_p.copy(); p1[45:95] += 3.2; p1 /= p1.sum()\np2 = base_p.copy(); p2[90:140] += 3.2; p2 /= p2.sum()\nprobs = [p0, p1, p2]\n\ndef sample_docs(counts_per_class: list[int]):\n    Xs, ys = [], []\n    for k, nk in enumerate(counts_per_class):\n        lengths = rng.integers(14, 28, size=nk)\n        docs = np.array([rng.multinomial(L, probs[k]) for L in lengths], dtype=float)\n        Xs.append(docs)\n        ys.append(np.full(nk, k, dtype=int))\n    return np.vstack(Xs), np.concatenate(ys)\n\nX_tr_raw, y_tr = sample_docs([900, 60, 40])\nX_te_raw, y_te = sample_docs([900, 60, 40])\ntfidf = TfidfTransformer(sublinear_tf=True).fit(X_tr_raw)\nX_tr, X_te = tfidf.transform(X_tr_raw), tfidf.transform(X_te_raw)\n\nmodels = [\n    (\"MultinomialNB(alpha=1.0)         \", MultinomialNB(alpha=1.0)),\n    (\"MultinomialNB(alpha=0.2)         \", MultinomialNB(alpha=0.2)),\n    (\"ComplementNB(alpha=1.0, norm=F)  \", ComplementNB(alpha=1.0, norm=False)),\n    (\"ComplementNB(alpha=0.5, norm=T)  \", ComplementNB(alpha=0.5, norm=True)),\n]\n\nprint(\"=== Benchmark Teks TF-IDF Timpang (90% / 6% / 4%): MultinomialNB vs ComplementNB ===\")\nprint(\"Model                             | Macro-F1 | Recall Kls-2 (4%) | Akurasi Total\")\nprint(\"-\" * 82)\nfor name, clf in models:\n    clf.fit(X_tr, y_tr)\n    pred = clf.predict(X_te)\n    mf1 = f1_score(y_te, pred, average=\"macro\")\n    rec_min = recall_score(y_te == 2, pred == 2)\n    acc = float(np.mean(pred == y_te))\n    print(f\"{name:33s} | {mf1:8.4f} | {rec_min*100:16.2f}% | {acc*100:12.2f}%\")\n\n# Audit Streaming Online Learning (partial_fit) — ekuivalensi penuh dengan batch fit\ncnb_batch = ComplementNB(alpha=0.5, norm=True).fit(X_tr, y_tr)\ncnb_stream = ComplementNB(alpha=0.5, norm=True)\nperm = rng.permutation(X_tr.shape[0])\nfor start in range(0, X_tr.shape[0], 100):\n    batch_idx = perm[start:start + 100]\n    cnb_stream.partial_fit(X_tr[batch_idx], y_tr[batch_idx], classes=np.array([0, 1, 2]))\n\nmax_diff = float(np.max(np.abs(cnb_batch.predict_proba(X_te) - cnb_stream.predict_proba(X_te))))\nprint(\"=== Verifikasi Streaming partial_fit (10 mini-batch) vs Batch Fit ===\")\nprint(f\"Max |proba_batch - proba_stream| = {max_diff:.2e} (ekuivalensi eksak pada O(V) memori!)\")",
          "expectedOutput": "=== Benchmark Teks TF-IDF Timpang (90% / 6% / 4%): MultinomialNB vs ComplementNB ===\nModel                             | Macro-F1 | Recall Kls-2 (4%) | Akurasi Total\n----------------------------------------------------------------------------------\nMultinomialNB(alpha=1.0)          |   0.3158 |             0.00% |        90.00%\nMultinomialNB(alpha=0.2)          |   0.3158 |             0.00% |        90.00%\nComplementNB(alpha=1.0, norm=F)   |   0.6287 |            77.50% |        83.90%\nComplementNB(alpha=0.5, norm=T)   |   0.5995 |            80.00% |        80.90%\n=== Verifikasi Streaming partial_fit (10 mini-batch) vs Batch Fit ===\nMax |proba_batch - proba_stream| = 1.11e-16 (ekuivalensi eksak pada O(V) memori!)",
          "actualOutput": "=== Benchmark Teks TF-IDF Timpang (90% / 6% / 4%): MultinomialNB vs ComplementNB ===\nModel                             | Macro-F1 | Recall Kls-2 (4%) | Akurasi Total\n----------------------------------------------------------------------------------\nMultinomialNB(alpha=1.0)          |   0.3158 |             0.00% |        90.00%\nMultinomialNB(alpha=0.2)          |   0.3158 |             0.00% |        90.00%\nComplementNB(alpha=1.0, norm=F)   |   0.6287 |            77.50% |        83.90%\nComplementNB(alpha=0.5, norm=T)   |   0.5995 |            80.00% |        80.90%\n=== Verifikasi Streaming partial_fit (10 mini-batch) vs Batch Fit ===\nMax |proba_batch - proba_stream| = 1.11e-16 (ekuivalensi eksak pada O(V) memori!)",
